inline bool span(const QByteArray &b,qint64 p,qint64 n){return p>=0&&n>=0&&p<=b.size()&&n<=b.size()-p;}
inline quint32 u(const QByteArray &b,qint64 p){return qFromLittleEndian<quint32>(b.constData()+p);}
inline QString text(const QByteArray &b,qint64 p,int n){auto raw=b.mid(p,n);int z=raw.indexOf('\0');return QString::fromUtf8(z<0?raw:raw.left(z));}
