inline QImage cached(Session &s,int index,QString &error,const std::atomic_bool &cancel){if(index<0||index>=s.images.size()){error="Source image is unavailable.";return {};}if(s.decoded.contains(index))return s.decoded[index];if(s.failures.contains(index)){error=s.failures[index];return {};}auto result=image(s.images[index],error,cancel);if(!cancel.load()){if(!result.isNull()){if(result.sizeInBytes()>AssetMemory::bytes()/4){error="Image exceeds the configured texture-cache budget.";return {};}if(s.decodedBytes+result.sizeInBytes()>AssetMemory::bytes()/4){s.decoded.clear();s.decodedBytes=0;}s.decoded[index]=result;s.decodedBytes+=result.sizeInBytes();}else s.failures[index]=error;}return result;}
inline QJsonArray imageCandidates(const QVector<Image> &images,const QJsonObject &base){QJsonArray out;for(int i=0;i<images.size();++i){auto t=images[i];if(!t.error.isEmpty())continue;auto row=base;row["name"]=t.name;row["profileId"]="native-linked-image";row["nativeDecoder"]=true;row["linkedImage"]=i;row["objectOffset"]=QString::number(i);row["width"]=t.width;row["height"]=t.height;row["settings"]=QJsonObject{{"offset","0"}};out.append(row);}return out;}
inline QMap<quint32,int> imageIndex(const QVector<Image> &images){QMap<quint32,int> result;QSet<quint32> ambiguous;for(int i=0;i<images.size();++i){auto t=images[i];if(result.contains(t.hash)){auto old=images[result[t.hash]];if(old.width!=t.width||old.height!=t.height||old.format!=t.format||old.pixels!=t.pixels||old.palette!=t.palette)ambiguous.insert(t.hash);}else result[t.hash]=i;}for(auto h:ambiguous)result.remove(h);return result;}
