inline MeshResult decode(ReadRequest source,const PatchList &patches,const QJsonObject &candidate,const std::atomic_bool &cancel,Session *session,const std::function<MeshResult(QJsonObject)> &raw){Session local;auto &s=session?*session:local;QMutexLocker lock(&s.mutex);MeshResult out;auto fail=[&](QString e){out.mesh.reset();out.error=e;return out;};QString error;if(!load(s,source,patches,candidate,cancel,error))return fail(error);auto draws=candidate["linkedDraws"].toArray();if(draws.isEmpty()||draws.size()>200000)return fail("Invalid material draw selection.");auto combined=std::make_shared<MeshData>();combined->hasUvs=true;bool rt=candidate["linkedFamily"]=="rtuned";std::shared_ptr<MemoryData> memory;if(rt){memory=std::make_shared<MemoryData>();memory->size=s.geometry.size();for(qint64 p=0;p<s.geometry.size();p+=MemoryData::BlockSize)memory->blocks.append(s.geometry.mid(p,MemoryData::BlockSize));}
 for(auto v:draws){if(cancel.load())return fail("Material preview canceled.");auto c=v.toObject();MeshResult part;if(rt){auto st=c["settings"].toObject();MeshSpec spec;spec.vertexOffset=st["vertexOffset"].toString().toLongLong();spec.vertexCount=st["vertexCount"].toInteger();spec.vertexStride=12;spec.positionType="Float32";spec.positionScale=1;spec.normals=false;spec.uv=st["uv"].toBool();spec.uvOffset=st["uvOffset"].toString().toLongLong();spec.uvStride=8;spec.uvType="Float32";spec.strip=true;spec.indexOffset=st["indexOffset"].toString().toLongLong();spec.indexCount=st["indexCount"].toInteger();spec.indexStride=2;spec.indexType="UInt16";ReadRequest child;child.memory=memory;child.expectedSize=memory->size;part=readMesh(child,{},spec);}else{if(c["profileId"]!="nfsu2-pc")return fail("Unsupported nested material geometry.");auto range=c["settings"].toObject();auto whole=c["linkedWholeSettings"].toObject();if(whole.isEmpty())return fail("Missing source solid settings.");c["settings"]=whole;part=raw(c);if(part.mesh&&part.error.isEmpty()){qint64 start=range["indexOffset"].toString().toLongLong(),end=start+range["indexCount"].toInteger()*2;QVector<quint32> triangles;QVector<MeshFaceSource> faces;for(int i=0;i<part.mesh->faceSources.size();++i){auto face=part.mesh->faceSources[i];if(face.offsets[0]<start||face.offsets[0]>=end)continue;for(auto at:face.offsets)if(at<start||at>=end)return fail("Material range cuts across a source face.");for(int k=0;k<3;++k)triangles.append(part.mesh->triangles[i*3+k]);faces.append(face);}part.mesh->triangles=triangles;part.mesh->faceSources=faces;}}if(!part.mesh||!part.error.isEmpty())return fail(part.error.isEmpty()?"Missing material geometry.":part.error);if(!AssetMemory::fits(combined->vertices.size()+part.mesh->vertices.size(),combined->triangles.size()+part.mesh->triangles.size()))return fail("Material geometry exceeds the configured memory budget.");QMap<quint32,quint32> remap;for(auto index:part.mesh->triangles){if(!remap.contains(index)){remap[index]=combined->vertices.size();combined->vertices.append(part.mesh->vertices[index]);if(!rt&&!part.mesh->vertexOffsets.isEmpty())combined->vertexOffsets.append(part.mesh->vertexOffsets[index]);}combined->triangles.append(remap[index]);}if(!rt)combined->faceSources+=part.mesh->faceSources;}
 int fallbackNormals=0;QVector<QVector3D> fallback(combined->vertices.size());for(int i=0;i<combined->triangles.size();i+=3){auto a=combined->triangles[i],b=combined->triangles[i+1],c=combined->triangles[i+2];auto point=[&](quint32 k){auto &v=combined->vertices[k];return QVector3D(v.position[0],v.position[1],v.position[2]);};auto n=QVector3D::crossProduct(point(b)-point(a),point(c)-point(a));if(n.lengthSquared()>1e-30f)for(auto k:{a,b,c})if(fallback[k].isNull())fallback[k]=n.normalized();}for(int i=0;i<combined->vertices.size();++i){auto &v=combined->vertices[i];if(std::hypot(double(v.normal[0]),double(v.normal[1]),double(v.normal[2]))<1e-30){auto n=fallback[i];if(n.isNull())n={0,1,0};for(int k=0;k<3;++k)v.normal[k]=n[k];++fallbackNormals;}}
 out.mesh=combined;auto resolved=candidate;if(!rt){bool ok=false;auto hash=candidate["linkedTextureHash"].toString().toUInt(&ok);resolved["linkedImage"]=ok?s.lookup.value(hash,-1):-1;}out.surface=surface(s,resolved,cancel);out.surface->material.sourceBindings["fallbackNormalVertices"]=fallbackNormals;if(!verify(source,s,error))return fail(error);if(cancel.load())return fail("Material decoding canceled.");return out;}
inline DecodedImage decodeImage(ReadRequest source,const PatchList &patches,const QJsonObject &candidate,const std::atomic_bool &cancel,Session *session){Session local;auto &s=session?*session:local;QMutexLocker lock(&s.mutex);DecodedImage out;if(!load(s,source,patches,candidate,cancel,out.error))return out;out.image=cached(s,candidate["linkedImage"].toInt(-1),out.error,cancel);if(!verify(source,s,out.error)||cancel.load()){out.image={};if(cancel.load()){out.cancelled=true;out.error="Image decoding canceled.";}}return out;}
